/* T10: min x^2-2x, x>=2  -> x=2, obj 0 (catches silent LP fallback) */
static void test_t10(void) {
    cur_name = "T10 QP min x^2-2x, x>=2 (no LP fallback)";
    P p; pbegin(&p);
    PRIMALtask_t t = p.task;
    PRIMAL_appendvars(t, 1);
    PRIMAL_putcj(t, 0, -2.0);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 2, 0);
    { int qi[] = {0}; int qj[] = {0}; double qv[] = {2};
      PRIMAL_putqobj(t, 1, qi, qj, qv); }
    PRIMALrescodee rc = PRIMAL_optimize(t);
    check_rc(rc, PRIMAL_RES_OK, "optimize ok");
    double x[1], po, y[0+1], slx[1];
    PRIMAL_getxx(t, PRIMAL_SOL_ITR, x);
    PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    close_enough(po, 0, "pobj=0");
    close_enough(x[0], 2, "x=2");
    PRIMAL_gety(t, PRIMAL_SOL_ITR, y); /* no constraints: y empty */
    (void)y;
    PRIMAL_getslx(t, PRIMAL_SOL_ITR, slx);
    close_enough(slx[0], -2, "slx=-2 (var at lower bound)");
    /* z = slx+sux = -(c+Qx) = -(-2+4) = -2 -> at LOWER bound */
    double sux[1]; PRIMAL_getsux(t, PRIMAL_SOL_ITR, sux);
    close_enough(slx[0] + sux[0], -2, "z_x=-2");
    expect_kkt(t, 1.0);
    pend(&p);
}

