    PRIMAL_makeenv(&env, NULL);
    PRIMAL_maketask(env, 0, 2, &t);
    PRIMAL_putcj(t, 0, -2.0); PRIMAL_putcj(t, 1, -2.0);
    int qi[] = {0,1}, qj[] = {0,1};
    double qv[] = {2.0,2.0};
    PRIMAL_putqobj(t, 2, qi, qj, qv);   /* Q = 2I */
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_RA, 0.0, 2.0);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_RA, 0.0, 2.0);
    PRIMALrescodee rc = PRIMAL_writedata(t, "/tmp/mc_t29.mps");
    check_rc(rc, PRIMAL_RES_OK, "writedata");
