/* ---------------- T267: readdataformat respects the declared format ----- */
/* copies file src to dst byte for byte. */
static void t267_cp(const char *src, const char *dst) {
    FILE *a = fopen(src, "rb"); if (!a) return;
    FILE *b = fopen(dst, "wb"); if (!b) { fclose(a); return; }
    char buf[4096]; size_t n;
    while ((n = fread(buf, 1, sizeof buf, a)) > 0) fwrite(buf, 1, n, b);
    fclose(a); fclose(b);
}

/* T267: readdataformat honors the declared format/compression rather than the extension. */
static void test_t267(void) {
    cur_name = "T267 readdataformat (declared format)";
    /* model min x0+x1 s.t. x0+x1 >= 3, optimum 3, written in the two formats with
     * the real extension, then copied with a neutral .txt extension */
    {
        P p; pbegin(&p);
        PRIMAL_appendvars(p.task, 2);
        PRIMAL_appendcons(p.task, 1);
        PRIMAL_putcj(p.task, 0, 1.0); PRIMAL_putcj(p.task, 1, 1.0);
        PRIMAL_putvarbound(p.task, 0, PRIMAL_BK_LO, 0, 0);
        PRIMAL_putvarbound(p.task, 1, PRIMAL_BK_LO, 0, 0);
        PRIMAL_putarow(p.task, 0, 2, (int[]){0, 1}, (double[]){1.0, 1.0});
        PRIMAL_putconbound(p.task, 0, PRIMAL_BK_LO, 3.0, 3.0);
        check_rc(PRIMAL_writedata(p.task, "/tmp/t267.mps"), PRIMAL_RES_OK, "write mps");
        check_rc(PRIMAL_writedata(p.task, "/tmp/t267.lp"), PRIMAL_RES_OK, "write lp");
        pend(&p);
    }
    t267_cp("/tmp/t267.mps", "/tmp/t267c.txt");   /* MPS in a .txt */
    t267_cp("/tmp/t267.lp",  "/tmp/t267a.txt");   /* LP  in a .txt */
    { FILE *f = fopen("/tmp/t267b.txt", "w"); if (f) { fputs(T256_LIN, f); fclose(f); } }
    /* A: MPS forced */
    {
        P p; pbegin(&p);
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_MPS,
                                       PRIMAL_COMPRESS_NONE), PRIMAL_RES_OK, "A MPS forced");
        check_rc(PRIMAL_optimize(p.task), PRIMAL_RES_OK, "A solve");
        double o = 0; PRIMAL_getprimalobj(p.task, PRIMAL_SOL_ITR, &o);
        close_enough_tol(o, 3.0, 1e-7, "A obj=3");
        pend(&p);
    }
    /* B: LP forced on a .txt; the extension (MPS) would fail -> discriminator */
    {
        P p; pbegin(&p);
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267a.txt", PRIMAL_DATA_FORMAT_LP,
                                       PRIMAL_COMPRESS_FREE), PRIMAL_RES_OK, "B LP forced");
        check_rc(PRIMAL_optimize(p.task), PRIMAL_RES_OK, "B solve");
        double o = 0; PRIMAL_getprimalobj(p.task, PRIMAL_SOL_ITR, &o);
        close_enough_tol(o, 3.0, 1e-7, "B obj=3");
        pend(&p);
    }
    {
        P p; pbegin(&p);
        PRIMALrescodee rc = PRIMAL_readdataformat(p.task, "/tmp/t267a.txt",
                                                  PRIMAL_DATA_FORMAT_EXTENSION, PRIMAL_COMPRESS_NONE);
        check(rc != PRIMAL_RES_OK, "B' .txt extension on an LP fails (MPS)");
        pend(&p);
    }
    /* C: OPF forced on a .txt */
    {
        P p; pbegin(&p);
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267b.txt", PRIMAL_DATA_FORMAT_OP,
                                       PRIMAL_COMPRESS_NONE), PRIMAL_RES_OK, "C OPF forced");
        check_rc(PRIMAL_optimize(p.task), PRIMAL_RES_OK, "C solve");
        double o = 0; PRIMAL_getprimalobj(p.task, PRIMAL_SOL_ITR, &o);
        close_enough_tol(o, 250.0/3.0, 1e-5, "C obj=250/3");
        pend(&p);
    }
    /* D: formats without a reader */
    {
        P p; pbegin(&p);
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_TASK,
                                       PRIMAL_COMPRESS_NONE), PRIMAL_RES_ERR_ARG, "D TASK rejected");
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_PTF,
                                       PRIMAL_COMPRESS_NONE), PRIMAL_RES_ERR_ARG, "D PTF rejected");
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_JSON_TASK,
                                       PRIMAL_COMPRESS_NONE), PRIMAL_RES_ERR_ARG, "D JSON rejected");
        pend(&p);
    }
    /* E: compression not linked */
    {
        P p; pbegin(&p);
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_MPS,
                                       PRIMAL_COMPRESS_GZIP), PRIMAL_RES_ERR_ARG, "E GZIP rejected");
        check_rc(PRIMAL_readdataformat(p.task, "/tmp/t267c.txt", PRIMAL_DATA_FORMAT_MPS,
                                       PRIMAL_COMPRESS_ZSTD), PRIMAL_RES_ERR_ARG, "E ZSTD rejected");
        pend(&p);
    }
}

/* ---------------- T268: env/task memory and global env ---------------- */
static void test_t268(void) {
    cur_name = "T268 env/task memory and global env";
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t task; PRIMAL_maketask(env, 0, 0, &task);
    double *a = (double *)PRIMAL_callocenv(env, 4, sizeof(double));
    check(a != NULL, "T268 callocenv not NULL");
    if (a) { for (int i = 0; i < 4; i++) a[i] = (double)i;
             check(a[2] == 2.0, "T268 callocenv writable"); }
    PRIMAL_freeenv(env, a);
    double *b = (double *)PRIMAL_calloctask(task, 4, sizeof(double));
    check(b != NULL, "T268 calloctask not NULL");
    if (b) check(b[3] == 0.0, "T268 calloctask zeroes");
    PRIMAL_freetask(task, b);
    double *c = (double *)PRIMAL_callocdbgenv(env, 2, sizeof(double), __FILE__, 1);
    check(c != NULL, "T268 callocdbgenv not NULL");
    PRIMAL_freedbgenv(env, c, __FILE__, 1);
    double *d = (double *)PRIMAL_callocdbgtask(task, 2, sizeof(double), __FILE__, 2);
    check(d != NULL, "T268 callocdbgtask not NULL");
    PRIMAL_freedbgtask(task, d, __FILE__, 2);
    check_rc(PRIMAL_globalenvinitialize(-1, NULL), PRIMAL_RES_OK, "T268 globalenvinitialize");
    check_rc(PRIMAL_globalenvfinalize(), PRIMAL_RES_OK, "T268 globalenvfinalize");
    check_rc(PRIMAL_checkmemenv(env, __FILE__, 1), PRIMAL_RES_OK, "T268 checkmemenv");
    check_rc(PRIMAL_checkmemtask(task, __FILE__, 1), PRIMAL_RES_OK, "T268 checkmemtask");
    PRIMAL_deletetask(&task);
    PRIMAL_deleteenv(&env);
}

/* ---------------- T269: the two double frees reported by -Wuse-after-free
 * (issue #4)
 *
 * GCC (Linux) reports `-Wuse-after-free` at two sites clang does not, and the
 * warning there is the conservative form of a REAL defect, not a cosmetic one.
 *
 *  A) stdform.c stdform_build(): the success path frees csr_*, lc3, uc3 BEFORE
 *     the Q block, and the error labels `a_fail` and `qfail` freed them a second
 *     time. Every `goto qfail` is downstream of that free, so the
 *     `qfail: free(lc3); free(uc3);` was a double free on all four sites
 *     (tri_add or tri_to_csc failing with hasQ). The same holds for `a_fail`,
 *     which can be reached both before and after the success free.
 *  B) primal_optimize.c (LP/QP bound tightening): `free(bt_lx); free(bt_ux);`
 *     appeared twice in a row in the allocation-failure branch.
 *
 * WHY THE TEST CANNOT REPRODUCE THE DOUBLE FREE
 * No allocation-failure hook exists in this library: reaching `qfail` needs a
 * malloc/realloc inside tri_add or tri_to_csc to return NULL, and without a
 * replaceable allocator the only way would be to exhaust the process memory. So
 * this test does not assert "the double free does not happen" -- it asserts the
 * **shape of the source**, which is what makes the defect impossible: every
 * buffer freed by the success path no longer appears in the downstream labels.
 * The defect is in the program text, not in a reachable behaviour, so that is
 * where it must be measured. The nominal path stays asserted just below, and it
 * is the one the success free goes through.
 */
static void t269_count_frees(const char *file, int after_line,
                             const char *const *names, int nnames, int *out) {
    FILE *fp = fopen(file, "r");
    if (!fp) { for (int k = 0; k < nnames; k++) out[k] = -1; return; }
    for (int k = 0; k < nnames; k++) out[k] = 0;      /* out[k]++ below: must start at 0 */
    char ln[512]; int lineno = 0;
    while (fgets(ln, sizeof ln, fp)) {
        lineno++;
        if (after_line > 0 && lineno <= after_line) continue;
        for (int k = 0; k < nnames; k++) {
            char pat[64]; snprintf(pat, sizeof pat, "free(%s)", names[k]);
            const char *p = ln;
            while ((p = strstr(p, pat)) != NULL) { out[k]++; p += strlen(pat); }
        }
    }
    fclose(fp);
}

static void test_t269(void) {
    cur_name = "T269 double frees (issue #4): no buffer freed twice";
    const char *sf_names[] = {"lc3", "uc3", "csr_ptr", "csr_j", "csr_v"};
    int n_sf[5];

    /* stdform.c: from the success free downward, each buffer must appear
     * exactly ONCE in the downstream labels (a_fail takes it back, qfail does
     * not). Before the fix they were 2: qfail freed them a second time. */
    t269_count_frees("stdform.c", 313, sf_names, 5, n_sf);
    check(n_sf[0] == 1, "T269 stdform lc3 freed once after the success path");
    check(n_sf[1] == 1, "T269 stdform uc3 freed once after the success path");
    check(n_sf[2] == 1, "T269 stdform csr_ptr freed once after success");
    check(n_sf[3] == 1, "T269 stdform csr_j freed once after success");
    check(n_sf[4] == 1, "T269 stdform csr_v freed once after success");

    /* primal_optimize.c: bt_lx/bt_ux are freed in four distinct branches
     * (allocation failure, two intermediate exits, the success exit). Before
     * the fix the first branch freed them twice in a row: it was 5. */
    const char *opt_names[] = {"bt_lx", "bt_ux"};
    int n_opt[2];
    t269_count_frees("primal_optimize.c", 0, opt_names, 2, n_opt);
    check(n_opt[0] == 4, "T269 primal_optimize bt_lx freed in the 4 branches, no double");
    check(n_opt[1] == 4, "T269 primal_optimize bt_ux freed in the 4 branches, no double");

    /* The NOMINAL path stays measurable and not just the shape: a model with a
     * quadratic part is the one that crosses the Q block and the success free
     * the defect had duplicated. */
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t task; PRIMAL_maketask(env, 1, 2, &task);
    PRIMAL_putcj(task, 0, -1.0);
    PRIMAL_putcj(task, 1, -1.0);
    PRIMAL_putvarbound(task, 0, PRIMAL_BK_LO, 0.0, 10.0);
    PRIMAL_putvarbound(task, 1, PRIMAL_BK_LO, 0.0, 10.0);
    PRIMAL_putarow(task, 0, 2, (int[]){0, 1}, (double[]){1.0, 1.0});
    PRIMAL_putconbound(task, 0, PRIMAL_BK_UP, 1.0, INFINITY);
    PRIMAL_putqobj(task, 2, (int[]){0, 1}, (int[]){0, 1}, (double[]){1.0, 1.0});
    PRIMAL_putobjsense(task, PRIMAL_OPTIMIZE_MINIMIZE);
    PRIMALrescodee rc = PRIMAL_optimize(task);
    check(rc == PRIMAL_RES_OK, "T269 QP: solve with quadratic part OK");
    if (rc == PRIMAL_RES_OK) {
        double x[2], pobj, dobj;
        PRIMAL_getxx(task, PRIMAL_SOL_BAS, x);
        PRIMAL_getprimalobj(task, PRIMAL_SOL_BAS, &pobj);
        PRIMAL_getdualobj(task, PRIMAL_SOL_BAS, &dobj);
        /* f(t) = -(x0+x1) + 0.5*(x0^2+x1^2) on the symmetric ray x0=x1=t is
         * -2t + t^2, whose unconstrained minimum is t = 1 with f = -1, NOT the
         * binding point t = 0.5 (which gives -0.75). The quadratic term is what
         * moves the optimum off the row, which is the point of using Q here. */
        check(fabs(x[0] - 1.0) < 1e-6 && fabs(x[1] - 1.0) < 1e-6, "T269 QP: x = (1,1)");
        check(fabs(pobj + 1.0) < 1e-6, "T269 QP: pobj = -1");
        check(fabs(pobj - dobj) < 1e-6, "T269 QP: strong duality");
    }
    PRIMAL_deletetask(&task);

    /* cbf.c: strdup must be declared, not implicitly declared as int (which on
     * x86-64 truncates the pointer to 32 bits). The feature macro must precede
     * the first include, otherwise it declares nothing. */
    FILE *cf = fopen("cbf.c", "r");
    check(cf != NULL, "T269 cbf.c leggibile");
    if (cf) {
        char ln[512]; int at_macro = 0, at_first_include = 0, lineno = 0, seen = 0;
        while (fgets(ln, sizeof ln, cf)) {
            lineno++;
            if (!seen && strstr(ln, "_POSIX_C_SOURCE")) { at_macro = lineno; seen = 1; }
            if (strstr(ln, "#include")) { at_first_include = lineno; break; }
        }
        fclose(cf);
        check(at_macro > 0, "T269 cbf.c: _POSIX_C_SOURCE present");
        check(at_macro < at_first_include,
              "T269 cbf.c: _POSIX_C_SOURCE before the first include (declares strdup)");
    }
    PRIMAL_deleteenv(&env);
}

/* T271 — an AFE edit must reach every solve encoding the AFE built (issue #19).
 * appendacc emits the rows of a linear domain directly and, for a conic domain,
 * numterms auxiliary variables plus the rows 'v_e - sum a_k x = b_e'; putdjc
 * emits selection binaries plus big-M rows. All three read the affine
 * expression once, at write time, so an accepted PRIMAL_putafeg /
 * PRIMAL_putafefentry afterwards used to leave the solve enforcing the OLD
 * expression. These are the three refreshes, each asserted on a value that only
 * moves if the edit reaches the encoding. */
static double t271_linacc(int edit) {
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t t; PRIMAL_maketask(env, 0, 0, &t);
    PRIMAL_appendvars(t, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0.0, INFINITY);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_UP, -INFINITY, 10.0);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putobjsense(t, PRIMAL_OPTIMIZE_MINIMIZE);
    PRIMAL_appendafes(t, 1);
    PRIMAL_putafefentry(t, 0, 0, 1.0);
    PRIMAL_putafeg(t, 0, -1.0);                     /* x - 1 */
    PRIMALint64t dom = -1; PRIMAL_appendrplusdomain(t, 1, &dom);
    PRIMAL_appendacc(t, dom, 1, (PRIMALint64t[]){0}, NULL);   /* x >= 1 */
    if (edit) PRIMAL_putafeg(t, 0, -3.0);           /* x >= 3 */
    double po = -1;
    if (PRIMAL_optimize(t) == PRIMAL_RES_OK) PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
    return po;
}

static double t271_conacc(int edit) {
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t t; PRIMAL_maketask(env, 0, 0, &t);
    PRIMAL_appendvars(t, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_FR, 0.0, 0.0);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putobjsense(t, PRIMAL_OPTIMIZE_MINIMIZE);
    PRIMAL_appendafes(t, 3);
    PRIMAL_putafefentry(t, 0, 0, 1.0); PRIMAL_putafeg(t, 0, 0.0);   /* t */
    PRIMAL_putafeg(t, 1, 1.0);                                      /* 1 */
    PRIMAL_putafeg(t, 2, 1.0);                                      /* 1 */
    PRIMALint64t dom = -1; PRIMAL_appendquadraticconedomain(t, 3, &dom);
    PRIMAL_appendacc(t, dom, 3, (PRIMALint64t[]){0, 1, 2}, NULL);
    if (edit) PRIMAL_putafeg(t, 1, 2.0);            /* t >= sqrt(4 + 1) */
    double po = -1;
    if (PRIMAL_optimize(t) == PRIMAL_RES_OK) PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
    return po;
}

static double t271_djc(int edit) {
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t t; PRIMAL_maketask(env, 0, 0, &t);
    PRIMAL_appendvars(t, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_RA, 0.0, 10.0);
    PRIMAL_putcj(t, 0, 1.0);
    PRIMAL_putobjsense(t, PRIMAL_OPTIMIZE_MAXIMIZE);
    PRIMAL_appendafes(t, 2);
    PRIMAL_putafefentry(t, 0, 0, 1.0); PRIMAL_putafeg(t, 0, -1.0);  /* x - 1 */
    PRIMAL_putafefentry(t, 1, 0, 1.0); PRIMAL_putafeg(t, 1, -2.0);  /* x - 2 */
    PRIMALint64t d1 = -1, d2 = -1;
    PRIMAL_appendrzerodomain(t, 1, &d1); PRIMAL_appendrzerodomain(t, 1, &d2);
    PRIMAL_appenddjcs(t, 1);
    PRIMALint64t doms[2] = {d1, d2}, afes[2] = {0, 1}, ts[2] = {1, 1};
    PRIMALrescodee rc = PRIMAL_putdjc(t, 0, 2, doms, 2, afes, NULL, 2, ts);
    if (edit) PRIMAL_putafeg(t, 1, -4.0);           /* clause x = 4 */
    double po = -1;
    if (rc == PRIMAL_RES_OK && PRIMAL_optimize(t) == PRIMAL_RES_OK)
        PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &po);
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
    return po;
}

static void test_t271(void) {
    cur_name = "T271 AFE edit reaches the ACC (linear, conic) and DJC encodings";
    double v;
    v = t271_linacc(0); check(fabs(v - 1.0) < 1e-7, "T271 linear ACC: x >= 1 first");
    v = t271_linacc(1); check(fabs(v - 3.0) < 1e-7, "T271 linear ACC: edit -> x >= 3");
    v = t271_conacc(0); check(fabs(v - 1.41421356) < 1e-4, "T271 conic ACC: t >= sqrt(2)");
    v = t271_conacc(1); check(fabs(v - 2.23606798) < 1e-4, "T271 conic ACC: edit -> sqrt(5)");
    v = t271_djc(0); check(fabs(v - 2.0) < 1e-6, "T271 DJC: max over {1,2} is 2");
    v = t271_djc(1); check(fabs(v - 4.0) < 1e-6, "T271 DJC: edit -> max over {1,4} is 4");
}

/* T270 — an unbounded LP relaxation is not, by itself, integer unboundedness.
 * min -x1 s.t. x1 - 2*x2 = rhs, x1,x2 integer >= 0 is unbounded as a relaxation
 * (x1 = 2*x2 + rhs -> inf) for either rhs. With rhs = 0 it HAS the integer point
 * (0,0), so it is genuinely unbounded; with rhs = 0.5 it has NO integer point at
 * all (x1 is always half-integer), so its honest answer is INFEASIBLE. The
 * refinement of the recession ray by the lcm of the denominators of its integer
 * coordinates is what makes the first sound, and the second is why the ray alone
 * is not. Before this, the root relaxation's status alone decided and the
 * infeasible twin came out UNBOUNDED. */
static void t270_mip(int half, PRIMALrescodee *rc, int *sta, int *pro) {
    PRIMALenv_t env; PRIMAL_makeenv(&env, NULL);
    PRIMALtask_t t; PRIMAL_maketask(env, 0, 0, &t);
    PRIMAL_appendvars(t, 2); PRIMAL_appendcons(t, 1);
    PRIMAL_putvarbound(t, 0, PRIMAL_BK_LO, 0.0, INFINITY);
    PRIMAL_putvartype(t, 0, PRIMAL_VAR_TYPE_INT);
    PRIMAL_putvarbound(t, 1, PRIMAL_BK_LO, 0.0, INFINITY);
    PRIMAL_putvartype(t, 1, PRIMAL_VAR_TYPE_INT);
    PRIMAL_putcj(t, 0, -1.0); PRIMAL_putcj(t, 1, 0.0);
    PRIMAL_putarow(t, 0, 2, (int[]){0, 1}, (double[]){1.0, -2.0});
    double rhs = half ? 0.5 : 0.0;
    PRIMAL_putconbound(t, 0, PRIMAL_BK_FX, rhs, rhs);
    PRIMAL_putobjsense(t, PRIMAL_OPTIMIZE_MINIMIZE);
    *rc = PRIMAL_optimize(t);
    PRIMAL_getsolsta(t, PRIMAL_SOL_ITR, (PRIMALsolstae *) sta);
    PRIMAL_getprosta(t, PRIMAL_SOL_ITR, (PRIMALprostae *) pro);
    PRIMAL_deletetask(&t); PRIMAL_deleteenv(&env);
}

static void test_t270(void) {
    cur_name = "T270 MIP: an unbounded relaxation is not integer unboundedness";
    PRIMALrescodee rc; int sta, pro;
    t270_mip(0, &rc, &sta, &pro);
    check_rc(rc, PRIMAL_RES_ERR_UNBOUNDED, "T270 feasible twin: genuinely unbounded");
    check(sta == 0 && pro == PRIMAL_PRO_STA_DUAL_INFEAS,
          "T270 feasible: the verdict is in prosta, no certificate");
    t270_mip(1, &rc, &sta, &pro);
    check(rc != PRIMAL_RES_ERR_UNBOUNDED, "T270 infeasible twin is NOT unbounded");
    check(sta == 0 && pro == PRIMAL_PRO_STA_PRIM_INFEAS,
          "T270 infeasible: PRIM_INFEAS, the same verdict without a certificate");
}

/* T272: the sparse QP engine solves a separable QP.  min sum (x_j^2 - x_j)
 * s.t. sum x_j <= 5, 0 <= x_j <= 10 has the optimum x_j = 5/n, objective
 * -5 + 25/n.  From n = 75 the standard form (a bound row per column) goes to
 * the sparse QP engine, whose reduced matrix K = A M^-1 A' is an arrowhead:
 * sparse, so it is factored under a fill-reducing ordering, and the direction
 * is right only if every solve with that factor undoes the ordering. */
static void test_t272(void) {
    cur_name = "T272 sparse QP engine: separable QP with a sparse reduced matrix";
    const int sizes[2] = { 75, 400 };
    for (int s = 0; s < 2; s++) {
        int n = sizes[s];
        P p; pbegin(&p);
        PRIMALtask_t t = p.task;
        PRIMAL_appendvars(t, n);
        PRIMAL_appendcons(t, 1);
        for (int j = 0; j < n; j++) {
            PRIMAL_putvarbound(t, j, PRIMAL_BK_RA, 0.0, 10.0);
            PRIMAL_putcj(t, j, -1.0);
            PRIMAL_putaij(t, 0, j, 1.0);
            PRIMAL_putqobjij(t, j, j, 2.0);
        }
        PRIMAL_putconbound(t, 0, PRIMAL_BK_UP, -INFINITY, 5.0);
        check_rc(PRIMAL_optimize(t), PRIMAL_RES_OK, "T272 optimize");
        double pobj = 0.0, want = -5.0 + 25.0 / n;
        PRIMAL_getprimalobj(t, PRIMAL_SOL_ITR, &pobj);
        check(fabs(pobj - want) <= 1e-7 * (1.0 + fabs(want)), "T272 objective -5 + 25/n");
        double *x = (double *)malloc((size_t)n * sizeof(double));
        if (x && PRIMAL_getxx(t, PRIMAL_SOL_ITR, x) == PRIMAL_RES_OK) {
            double sum = 0.0, viol = 0.0;
            for (int j = 0; j < n; j++) {
                sum += x[j];
                if (-x[j] > viol) viol = -x[j];
                if (x[j] - 10.0 > viol) viol = x[j] - 10.0;
            }
            if (sum - 5.0 > viol) viol = sum - 5.0;
            check(viol <= 1e-7, "T272 the point measures feasible");
        } else {
            check(0, "T272 getxx");
        }
        free(x);
        pend(&p);
    }
}

